describe('ArticleService', () => {
  let articleService: ArticleService;
  let mockArticleRepo: MockArticleRepository;
  let mockUserRepo: MockUserRepository;

  beforeEach(() => {
    mockArticleRepo = new MockArticleRepository();
    mockUserRepo = new MockUserRepository();
    articleService = new ArticleService(mockArticleRepo, mockUserRepo);

    mockUserRepo.addUser({
      id: 1,
      email: 'author@example.com',
      username: 'author',
      passwordHash: 'hash',
      bio: null,
      image: null,
      createdAt: new Date(),
      updatedAt: new Date()
    });
  });

  describe('getArticle', () => {
    it('get_existing_article_returns_article_with_body', async () => {
      mockArticleRepo.addArticle({
        slug: 'test-article',
        title: 'Test Article',
        body: 'Article body content'
      });

      const article = await articleService.getArticle('test-article');

      expect(article.slug).toBe('test-article');
      expect(article.body).toBe('Article body content');
    });

    it('get_nonexistent_article_throws_NotFoundError', async () => {
      await expect(
        articleService.getArticle('nonexistent')
      ).rejects.toThrow(NotFoundError);
    });
  });

  describe('createArticle', () => {
    it('create_article_generates_slug_from_title', async () => {
      const article = await articleService.createArticle(
        {
          title: 'How to Train Your Dragon',
          description: 'Ever wonder how?',
          body: 'You have to believe',
          tagList: ['dragons']
        },
        1
      );

      expect(article.slug).toBe('how-to-train-your-dragon');
      expect(article.title).toBe('How to Train Your Dragon');
      expect(article.tagList).toEqual(['dragons']);
    });

    it('create_article_with_duplicate_title_makes_slug_unique', async () => {
      mockArticleRepo.addArticle({ slug: 'test-title' });

      const article = await articleService.createArticle(
        { title: 'Test Title', description: 'Desc', body: 'Body' },
        1
      );

      expect(article.slug).toMatch(/^test-title-[a-z0-9]{6}$/);
    });
  });

  describe('updateArticle', () => {
    beforeEach(() => {
      mockArticleRepo.addArticle({
        slug: 'original-slug',
        title: 'Original Title',
        author: { username: 'author', bio: null, image: null, following: false }
      });
    });

    it('update_article_by_author_returns_updated_article', async () => {
      const updated = await articleService.updateArticle(
        'original-slug',
        { title: 'Updated Title' },
        1
      );

      expect(updated.title).toBe('Updated Title');
    });

    it('update_nonexistent_article_throws_NotFoundError', async () => {
      await expect(
        articleService.updateArticle('nonexistent', { title: 'New' }, 1)
      ).rejects.toThrow(NotFoundError);
    });

    it('update_article_by_non_author_throws_AuthorizationError', async () => {
      mockUserRepo.addUser({
        id: 2,
        email: 'other@example.com',
        username: 'other',
        passwordHash: 'hash',
        bio: null,
        image: null,
        createdAt: new Date(),
        updatedAt: new Date()
      });

      await expect(
        articleService.updateArticle('original-slug', { title: 'Hacked' }, 2)
      ).rejects.toThrow(AuthorizationError);
    });
  });

  describe('deleteArticle', () => {
    beforeEach(() => {
      mockArticleRepo.addArticle({
        slug: 'to-delete',
        author: { username: 'author', bio: null, image: null, following: false }
      });
    });

    it('delete_article_by_author_removes_article', async () => {
      await articleService.deleteArticle('to-delete', 1);

      const article = await mockArticleRepo.findBySlug('to-delete');
      expect(article).toBeNull();
    });

    it('delete_article_by_non_author_throws_AuthorizationError', async () => {
      mockUserRepo.addUser({
        id: 2,
        email: 'other@example.com',
        username: 'other',
        passwordHash: 'hash',
        bio: null,
        image: null,
        createdAt: new Date(),
        updatedAt: new Date()
      });

      await expect(
        articleService.deleteArticle('to-delete', 2)
      ).rejects.toThrow(AuthorizationError);
    });
  });

  describe('favoriteArticle', () => {
    beforeEach(() => {
      mockArticleRepo.addArticle({ slug: 'to-favorite' });
    });

    it('favorite_article_returns_article_with_favorited_true', async () => {
      const article = await articleService.favoriteArticle('to-favorite', 1);

      expect(article.favorited).toBe(true);
      expect(article.favoritesCount).toBe(1);
    });

    it('favorite_nonexistent_article_throws_NotFoundError', async () => {
      await expect(
        articleService.favoriteArticle('nonexistent', 1)
      ).rejects.toThrow(NotFoundError);
    });
  });

  describe('unfavoriteArticle', () => {
    beforeEach(() => {
      const article = mockArticleRepo.addArticle({ slug: 'favorited' });
      article.favorited = true;
      article.favoritesCount = 1;
    });

    it('unfavorite_article_returns_article_with_favorited_false', async () => {
      const article = await articleService.unfavoriteArticle('favorited', 1);

      expect(article.favorited).toBe(false);
      expect(article.favoritesCount).toBe(0);
    });
  });
});

import { AuthService } from './auth.service';
import { IUserRepository, UserEntity } from '../repositories/IUserRepository';
import { ValidationError, AuthenticationError } from '../errors/AppError';
import argon2 from 'argon2';

// Mock repository
class MockUserRepository implements IUserRepository {
  private users: UserEntity[] = [];
  private nextId = 1;

  async findByEmail(email: string): Promise<UserEntity | null> {
    return this.users.find(u => u.email === email) || null;
  }

  async findByUsername(username: string): Promise<UserEntity | null> {
    return this.users.find(u => u.username === username) || null;
  }

  async findById(id: number): Promise<UserEntity | null> {
    return this.users.find(u => u.id === id) || null;
  }

  async create(data: any): Promise<UserEntity> {
    const user: UserEntity = {
      id: this.nextId++,
      email: data.email,
      username: data.username,
      passwordHash: data.passwordHash,
      bio: data.bio || null,
      image: data.image || null,
      createdAt: new Date(),
      updatedAt: new Date()
    };
    this.users.push(user);
    return user;
  }

  async update(id: number, data: any): Promise<UserEntity> {
    const user = this.users.find(u => u.id === id);
    if (!user) throw new Error('User not found');

    Object.assign(user, {
      ...data,
      updatedAt: new Date()
    });
    return user;
  }

  async isFollowing(): Promise<boolean> {
    return false;
  }

  async follow(): Promise<void> {}
  async unfollow(): Promise<void> {}
}

describe('AuthService', () => {
  let authService: AuthService;
  let mockRepository: MockUserRepository;

  beforeEach(() => {
    mockRepository = new MockUserRepository();
    authService = new AuthService(mockRepository);
  });

  describe('register', () => {
    it('creates_user_with_valid_data_returns_user_with_token', async () => {
      const result = await authService.register({
        email: 'test@example.com',
        username: 'testuser',
        password: 'password123'
      });

      expect(result.email).toBe('test@example.com');
      expect(result.username).toBe('testuser');
      expect(result.token).toBeDefined();
      expect(result.bio).toBeNull();
      expect(result.image).toBeNull();
    });

    it('hashes_password_with_argon2', async () => {
      await authService.register({
        email: 'test@example.com',
        username: 'testuser',
        password: 'password123'
      });

      const user = await mockRepository.findByEmail('test@example.com');
      expect(user).not.toBeNull();

      const isValid = await argon2.verify(user!.passwordHash, 'password123');
      expect(isValid).toBe(true);
    });

    it('register_with_duplicate_email_throws_ValidationError', async () => {
      await authService.register({
        email: 'test@example.com',
        username: 'user1',
        password: 'password123'
      });

      await expect(
        authService.register({
          email: 'test@example.com',
          username: 'user2',
          password: 'password123'
        })
      ).rejects.toThrow(ValidationError);
    });

    it('register_with_duplicate_username_throws_ValidationError', async () => {
      await authService.register({
        email: 'user1@example.com',
        username: 'testuser',
        password: 'password123'
      });

      await expect(
        authService.register({
          email: 'user2@example.com',
          username: 'testuser',
          password: 'password123'
        })
      ).rejects.toThrow(ValidationError);
    });
  });

  describe('login', () => {
    beforeEach(async () => {
      await authService.register({
        email: 'test@example.com',
        username: 'testuser',
        password: 'password123'
      });
    });

    it('login_with_valid_credentials_returns_user_with_token', async () => {
      const result = await authService.login({
        email: 'test@example.com',
        password: 'password123'
      });

      expect(result.email).toBe('test@example.com');
      expect(result.username).toBe('testuser');
      expect(result.token).toBeDefined();
    });

    it('login_with_invalid_email_throws_ValidationError', async () => {
      await expect(
        authService.login({
          email: 'wrong@example.com',
          password: 'password123'
        })
      ).rejects.toThrow(ValidationError);
    });

    it('login_with_invalid_password_throws_ValidationError', async () => {
      await expect(
        authService.login({
          email: 'test@example.com',
          password: 'wrongpassword'
        })
      ).rejects.toThrow(ValidationError);
    });
  });

  describe('getCurrentUser', () => {
    it('get_existing_user_returns_user_with_fresh_token', async () => {
      const registered = await authService.register({
        email: 'test@example.com',
        username: 'testuser',
        password: 'password123'
      });

      const user = await mockRepository.findByEmail('test@example.com');
      const result = await authService.getCurrentUser(user!.id);

      expect(result.email).toBe('test@example.com');
      expect(result.token).toBeDefined();
      expect(result.token).not.toBe(registered.token); // Fresh token
    });

    it('get_nonexistent_user_throws_AuthenticationError', async () => {
      await expect(
        authService.getCurrentUser(999)
      ).rejects.toThrow(AuthenticationError);
    });
  });

  describe('updateUser', () => {
    let userId: number;

    beforeEach(async () => {
      const user = await mockRepository.create({
        email: 'test@example.com',
        username: 'testuser',
        passwordHash: await argon2.hash('password123')
      });
      userId = user.id;
    });

    it('update_email_returns_user_with_new_email', async () => {
      const result = await authService.updateUser(userId, {
        email: 'newemail@example.com'
      });

      expect(result.email).toBe('newemail@example.com');
    });

    it('update_bio_and_image_returns_user_with_new_values', async () => {
      const result = await authService.updateUser(userId, {
        bio: 'New bio',
        image: 'https://example.com/image.jpg'
      });

      expect(result.bio).toBe('New bio');
      expect(result.image).toBe('https://example.com/image.jpg');
    });

    it('update_with_duplicate_email_throws_ValidationError', async () => {
      await mockRepository.create({
        email: 'other@example.com',
        username: 'otheruser',
        passwordHash: await argon2.hash('password123')
      });

      await expect(
        authService.updateUser(userId, {
          email: 'other@example.com'
        })
      ).rejects.toThrow(ValidationError);
    });
  });
});

