describe('ProfileService', () => {
  let profileService: ProfileService;
  let mockProfileRepo: MockProfileRepository;
  let mockUserRepo: MockUserRepository;

  beforeEach(() => {
    mockProfileRepo = new MockProfileRepository();
    mockUserRepo = new MockUserRepository();
    profileService = new ProfileService(mockProfileRepo, mockUserRepo);
  });

  describe('getProfile', () => {
    beforeEach(() => {
      mockProfileRepo.setProfile({
        username: 'johndoe',
        bio: 'Software developer',
        image: 'https://example.com/avatar.jpg',
        following: false
      });
    });

    it('get_existing_profile_without_auth_returns_profile_with_following_false', async () => {
      const profile = await profileService.getProfile('johndoe');

      expect(profile).toEqual({
        username: 'johndoe',
        bio: 'Software developer',
        image: 'https://example.com/avatar.jpg',
        following: false
      });
    });

    it('get_existing_profile_with_auth_returns_profile_with_follow_status', async () => {
      mockProfileRepo.setProfile({
        username: 'johndoe',
        bio: 'Software developer',
        image: 'https://example.com/avatar.jpg',
        following: true
      });

      const profile = await profileService.getProfile('johndoe', 1);

      expect(profile.username).toBe('johndoe');
      expect(profile.following).toBe(true);
    });

    it('get_nonexistent_profile_throws_NotFoundError', async () => {
      await expect(
        profileService.getProfile('nonexistent')
      ).rejects.toThrow(NotFoundError);
    });
  });

  describe('followUser', () => {
    beforeEach(() => {
      mockUserRepo.addUser({
        id: 1,
        email: 'current@example.com',
        username: 'currentuser',
        passwordHash: 'hash',
        bio: null,
        image: null,
        createdAt: new Date(),
        updatedAt: new Date()
      });

      mockUserRepo.addUser({
        id: 2,
        email: 'target@example.com',
        username: 'targetuser',
        passwordHash: 'hash',
        bio: 'Target bio',
        image: 'https://example.com/target.jpg',
        createdAt: new Date(),
        updatedAt: new Date()
      });
    });

    it('follow_existing_user_returns_profile_with_following_true', async () => {
      const profile = await profileService.followUser('targetuser', 1);

      expect(profile).toEqual({
        username: 'targetuser',
        bio: 'Target bio',
        image: 'https://example.com/target.jpg',
        following: true
      });

      const isFollowing = await mockUserRepo.isFollowing(1, 2);
      expect(isFollowing).toBe(true);
    });

    it('follow_already_followed_user_is_idempotent', async () => {
      await profileService.followUser('targetuser', 1);
      const profile = await profileService.followUser('targetuser', 1);

      expect(profile.following).toBe(true);
    });

    it('follow_nonexistent_user_throws_NotFoundError', async () => {
      await expect(
        profileService.followUser('nonexistent', 1)
      ).rejects.toThrow(NotFoundError);
    });

    it('follow_self_throws_ValidationError', async () => {
      await expect(
        profileService.followUser('currentuser', 1)
      ).rejects.toThrow(ValidationError);
    });
  });

  describe('unfollowUser', () => {
    beforeEach(() => {
      mockUserRepo.addUser({
        id: 1,
        email: 'current@example.com',
        username: 'currentuser',
        passwordHash: 'hash',
        bio: null,
        image: null,
        createdAt: new Date(),
        updatedAt: new Date()
      });

      mockUserRepo.addUser({
        id: 2,
        email: 'target@example.com',
        username: 'targetuser',
        passwordHash: 'hash',
        bio: 'Target bio',
        image: null,
        createdAt: new Date(),
        updatedAt: new Date()
      });
    });

    it('unfollow_followed_user_returns_profile_with_following_false', async () => {
      await mockUserRepo.follow(1, 2);

      const profile = await profileService.unfollowUser('targetuser', 1);

      expect(profile).toEqual({
        username: 'targetuser',
        bio: 'Target bio',
        image: null,
        following: false
      });

      const isFollowing = await mockUserRepo.isFollowing(1, 2);
      expect(isFollowing).toBe(false);
    });

    it('unfollow_not_followed_user_is_idempotent', async () => {
      const profile = await profileService.unfollowUser('targetuser', 1);

      expect(profile.following).toBe(false);
    });

    it('unfollow_nonexistent_user_throws_NotFoundError', async () => {
      await expect(
        profileService.unfollowUser('nonexistent', 1)
      ).rejects.toThrow(NotFoundError);
    });
  });
});

import { TagService } from './tag.service';
import { ITagRepository, TagEntity } from '../repositories/ITagRepository';

// Mock repository
class MockTagRepository implements ITagRepository {
  private tags: TagEntity[] = [];

  addTag(name: string): void {
    this.tags.push({ id: this.tags.length + 1, name });
  }

  async findByName(name: string): Promise<TagEntity | null> {
    return this.tags.find(t => t.name === name) || null;
  }

  async upsert(name: string): Promise<TagEntity> {
    const existing = this.tags.find(t => t.name === name);
    if (existing) return existing;

    const tag: TagEntity = { id: this.tags.length + 1, name };
    this.tags.push(tag);
    return tag;
  }

  async upsertMany(names: string[]): Promise<TagEntity[]> {
    return Promise.all(names.map(name => this.upsert(name)));
  }

  async listAll(): Promise<string[]> {
    return this.tags.map(t => t.name);
  }
}

describe('TagService', () => {
  let tagService: TagService;
  let mockTagRepo: MockTagRepository;

  beforeEach(() => {
    mockTagRepo = new MockTagRepository();
    tagService = new TagService(mockTagRepo);
  });

  describe('getAllTags', () => {
    it('get_all_tags_with_no_tags_returns_empty_array', async () => {
      const tags = await tagService.getAllTags();

      expect(tags).toEqual([]);
    });

    it('get_all_tags_returns_all_unique_tags', async () => {
      mockTagRepo.addTag('reactjs');
      mockTagRepo.addTag('angular');
      mockTagRepo.addTag('nodejs');

      const tags = await tagService.getAllTags();

      expect(tags).toHaveLength(3);
      expect(tags).toContain('reactjs');
      expect(tags).toContain('angular');
      expect(tags).toContain('nodejs');
    });

    it('get_all_tags_returns_tags_in_database_order', async () => {
      mockTagRepo.addTag('dragons');
      mockTagRepo.addTag('training');
      mockTagRepo.addTag('javascript');

      const tags = await tagService.getAllTags();

      expect(tags).toEqual(['dragons', 'training', 'javascript']);
    });
  });
});
